func _touch(rudy: Rudy, delta: float) -> void:
	if not rudy.can_be_touched():
		return
	var top := global_position.y - HEIGHT
	var soles_before := rudy.global_position.y - rudy.velocity.y * delta
	if rudy.velocity.y > 0.0 and soles_before <= top + STOMP_MARGIN:
		defeat(&"stomp")
		rudy.bounce()
	else:
		rudy.take_hit(global_position)

func _swing(delta: float) -> void:
	_sword_box.position.x = slash_reach * facing
	var live := is_slashing() and _slash_clock >= slash_live_from and _slash_clock <= slash_live_to
	_sword_box.disabled = not live
	if live:
		_slash_query.transform = _sword_box.global_transform
		for contact in get_world_2d().direct_space_state.intersect_shape(_slash_query, 8):
			if contact.collider is Goblin:
				(contact.collider as Goblin).defeat(&"slash")

## The level it is heading for, in dB: the deepest dip in force, or SILENCE
## while it fades out.
func target_db() -> float:
	if _fading_out:
		return SILENCE
	var level := 0.0
	for db: float in _dips.values():
		level = minf(level, db)
	return level

func _process(_delta: float) -> void:
	if Input.is_action_just_pressed(&"pause"):
		_main.toggle_pause()
	if Input.is_action_just_pressed(&"mute_music"):
		toggle_mute(Music.BUS)
	if Input.is_action_just_pressed(&"mute_sfx"):
		toggle_mute(Sfx.BUS)


static func toggle_mute(bus_name: StringName) -> void:
	var bus := AudioServer.get_bus_index(bus_name)
	AudioServer.set_bus_mute(bus, not AudioServer.is_bus_mute(bus))
